const label = (lang: string, field: string) => t(lang, `field.demo.invoice.${field}`)
/** Live rows of the table (a list's total without filters). */
const count = async () =>
  Number((await ds.query('SELECT COUNT(*) AS n FROM demo_invoice WHERE deleted_at IS NULL'))[0].n)
const idsOf = (res: request.Response) => res.body.data.items.map((r: { id: number }) => r.id)

async function user(name: string, roles: number[]) {
  const id = await insertRow(ds.manager, 'iam_user', {
    username: PREFIX + name,
    display_name: name,
    password_hash: 'not-used-by-this-spec',
    password_changed_at: new Date(),
  })
  for (const r of roles)
    await ds.query('INSERT INTO iam_user_roles (user_id, role_id) VALUES (?, ?)', [id, r])
  userIds.push(id)
  return (await signIn(app, PREFIX + name)).accessToken
}

beforeAll(async () => {
  const moduleRef = await Test.createTestingModule({ imports: [AppModule] }).compile()
  app = setupApp(moduleRef.createNestApplication<NestExpressApplication>({ logger: false }))
  await app.listen(0, '127.0.0.1')
  ds = app.get<DataSource>(getDataSourceToken())
  redis = app.get(REDIS)
  i18n = app.get(I18nService)
  await cleanRedis(redis)
  lastId = Number((await ds.query('SELECT COALESCE(MAX(id), 0) AS n FROM demo_invoice'))[0].n)
  roleId = await insertRow(ds.manager, 'iam_role', {
    code: `${PREFIX}reader`,
    name: `${PREFIX}reader`,
    data_scope: 'all',
  })
  const browse = await findId(ds.manager, 'iam_menu', { perms: invoicePerms.browse })
  await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [roleId, browse])
  tokens.admin = (await signIn(app)).accessToken
  tokens.reader = await user('reader', [roleId])
  tokens.plain = await user('plain', [])
})

afterAll(async () => {
  if (ds) {
    await ds.query('DELETE FROM demo_invoice_line WHERE invoice_id > ?', [lastId])
    await ds.query('DELETE FROM demo_invoice WHERE id > ?', [lastId])
    if (userIds.length) {
      await ds.query('DELETE FROM iam_user_roles WHERE user_id IN (?)', [userIds])
      await ds.query('DELETE FROM iam_user WHERE id IN (?)', [userIds])
    }
    await ds.query('DELETE FROM iam_role_menus WHERE role_id = ?', [roleId])
    await ds.query('DELETE FROM iam_role WHERE id = ?', [roleId])
  }
  if (redis) await cleanRedis(redis)
  await app?.close()
})

describe('CRUD', () => {
  it('create → 201 with the row (defaults filled, audit columns set); get returns it', async () => {
    const tag = unique()
    const res = await create(body(tag)).expect(201)
    const row = res.body.data
    expect(row).toMatchObject({
      id: expect.any(Number),
      ...body(tag),
      issuedAt: null,
      createdBy: expect.any(Number),
    })
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt)
    const got = await call('admin', 'get', `/${row.id}`).expect(200)
    expect(got.body.data).toEqual(row)
  })

  it('list: newest first by the sort whitelist, all live rows counted, paging, created_at range', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const res = await list({ sort: '-id', pageSize: 3 })
    expect(idsOf(res)).toEqual([...ids].reverse())
    expect(res.body.data.total).toBe(await count())
    expect(idsOf(await list({ sort: '-id', page: 2, pageSize: 2 }))[0]).toBe(ids[0])
    // created_at from / to: instants (ISO-8601 with an offset)
    const [{ at }] = await ds.query('SELECT created_at AS at FROM demo_invoice WHERE id = ?', [
      ids[0],
    ])
    const around = (ms: number) => new Date(at.getTime() + ms).toISOString()
    expect(
      idsOf(await list({ createdAtFrom: around(-1000), createdAtTo: around(1000), sort: '-id' })),
    ).toContain(ids[0])
    expect(idsOf(await list({ createdAtTo: around(-1000), sort: '-id' }))).not.toContain(ids[0])
  })

  it('list: text filters contain (LIKE wildcards literal)', async () => {
    const tag = unique()
    for (const suffix of ['a', 'b', 'c']) await add(body(`${tag}-${suffix}`))
    await add(body(`${tag}_x`))

    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const keys = (res: request.Response) =>
      res.body.data.items.map((r: { invoiceNo: string }) => r.invoiceNo)
    const res = await list({ invoiceNo: `${tag}-`, sort: '-id' })
    expect(keys(res)).toEqual([`${tag}-c`, `${tag}-b`, `${tag}-a`])
    expect(res.body.data.total).toBe(3)
    // `%` and `_` in the filter are plain characters
    expect(keys(await list({ invoiceNo: `${tag}_` }))).toEqual([`${tag}_x`])
    expect(keys(await list({ buyer: `${tag}-b buyer` }))).toEqual([`${tag}-b`])
    const page2 = await list({ invoiceNo: `${tag}-`, sort: 'id', page: 2, pageSize: 2 })
    expect(keys(page2)).toEqual([`${tag}-c`])
    expect(page2.body.data.total).toBe(3)
  })

  it('update changes the fields sent and keeps the others', async () => {
    const tag = unique()
    const { id } = await add(body(tag))
    await call('admin', 'put', `/${id}`, { buyer: `${tag} renamed` }).expect(200)
    expect((await call('admin', 'get', `/${id}`)).body.data).toMatchObject({
      ...body(tag),
      buyer: `${tag} renamed`,
    })
  })

  it('a row PUT back as loaded (nulls included, as the edit form sends it) → 200, unchanged', async () => {
    const row = await add(body(unique()))
    const loaded = Object.fromEntries(FORM.map((f) => [f, row[f]]))
    await call('admin', 'put', `/${row.id}`, loaded).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject(loaded)
  })

  it('delete and batch delete (soft: the rows stay, marked deleted)', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    await call('admin', 'delete', `/${ids[0]}`).expect(200)
    await call('admin', 'post', '/batch-delete', { ids: ids.slice(1) }).expect(200)
    expect(
      await ds.query('SELECT id FROM demo_invoice WHERE id IN (?) AND deleted_at IS NULL', [ids]),
    ).toEqual([])
    expect(await ds.query('SELECT id FROM demo_invoice WHERE id IN (?)', [ids])).toHaveLength(3)
    await call('admin', 'get', `/${ids[0]}`).expect(404)
    // unique among live rows only: a deleted row's invoiceNo can be used again
    const { invoiceNo } = (
      await ds.query('SELECT invoice_no AS invoiceNo FROM demo_invoice WHERE id = ?', [ids[0]])
    )[0]
    await create({ ...body(unique()), invoiceNo }).expect(201)
  })
})

describe('lines (master-sub): saved with the invoice as one document', () => {
  it('create with rows → 201 with them in order (ids, invoiceId set); GET /:id answers the same', async () => {
    const tag = unique()
    const saved = await add(
      body(tag, { lines: [invoiceLine(`${tag}-a`), invoiceLine(`${tag}-b`)] }),
    )
    expect(saved.lines).toMatchObject([invoiceLine(`${tag}-a`), invoiceLine(`${tag}-b`)])
    expect(
      saved.lines.map((r: { id: number; invoiceId: number }) => [typeof r.id, r.invoiceId]),
    ).toEqual([
      ['number', saved.id],
      ['number', saved.id],
    ])
    expect((await call('admin', 'get', `/${saved.id}`).expect(200)).body.data).toEqual(saved)
  })

  it('update diffs the rows: with an id changed, without one added, not sent deleted (soft); left out kept', async () => {
    const tag = unique()
    const saved = await add(
      body(tag, { lines: [invoiceLine(`${tag}-a`), invoiceLine(`${tag}-b`)] }),
    )
    const [a, b] = saved.lines
    await call('admin', 'put', `/${saved.id}`, {
      lines: [{ ...invoiceLine(`${tag}-a2`), id: a.id }, invoiceLine(`${tag}-c`)],
    }).expect(200)
    const rows = async () =>
      (await call('admin', 'get', `/${saved.id}`).expect(200)).body.data.lines
    const after = await rows()
    expect(after).toMatchObject([
      { ...invoiceLine(`${tag}-a2`), id: a.id },
      invoiceLine(`${tag}-c`),
    ])
    expect(
      await ds.query('SELECT deleted_at IS NOT NULL AS gone FROM demo_invoice_line WHERE id = ?', [
        b.id,
      ]),
    ).toEqual([{ gone: 1 }])
    // no list sent: the rows stay as they are
    await call('admin', 'put', `/${saved.id}`, {}).expect(200)
    expect(await rows()).toEqual(after)
    await call('admin', 'put', `/${saved.id}`, { lines: [] }).expect(200)
    expect(await rows()).toEqual([])
  })

  it('a row id of another invoice → 404 and nothing written (the fields sent with it neither)', async () => {
    const tag = unique()
    const other = await add(body(unique(), { lines: [invoiceLine(`${tag}-x`)] }))
    const mine = await add(body(tag, { lines: [invoiceLine(`${tag}-a`)] }))
    const stolen = { ...invoiceLine(`${tag}-y`), id: other.lines[0].id }
    const res = await call('admin', 'put', `/${mine.id}`, {
      buyer: `${tag} changed`.slice(0, 128),
      lines: [stolen],
    })
    expect(res.status).toBe(404)
    expect(res.body.code).toBe(Err.NOT_FOUND.code)
    for (const kept of [mine, other])
      expect((await call('admin', 'get', `/${kept.id}`).expect(200)).body.data).toEqual(kept)
    const before = await count()
    expect((await create(body(unique(), { lines: [stolen] }))).status).toBe(404)
    expect(await count()).toBe(before)
  })

  it('delete: the invoice goes with its rows (soft: they stay, marked deleted)', async () => {
    const tag = unique()
    const { id } = await add(
      body(tag, { lines: [invoiceLine(`${tag}-a`), invoiceLine(`${tag}-b`)] }),
    )
    await call('admin', 'delete', `/${id}`).expect(200)
    expect(
      await ds.query(
        'SELECT deleted_at IS NOT NULL AS gone FROM demo_invoice_line WHERE invoice_id = ?',
        [id],
      ),
    ).toEqual([{ gone: 1 }, { gone: 1 }])
  })

  it('400: a bad row field, with its path and translated label; nothing written', async () => {
    const tag = unique()
    const before = await count()
    const res = await create(
      body(tag, { lines: [invoiceLine(`${tag}-a`), invoiceLine(`${tag}-b`, { item: '' })] }),
    ).expect(400)
    expect(res.body.errors).toEqual([
      {
        path: 'lines.1.item',
        msg: t('zh-CN', 'validation.required', { field: label('zh-CN', 'item') }),
      },
    ])
    expect(label('en-US', 'item')).not.toMatch(/^field\./)
    expect(await count()).toBe(before)
  })
})

describe('errors', () => {
  it('403 per permission: browse-only may list, not view/create/modify/delete; no perm → no list', async () => {
    const { id } = await add(body(unique()))
    await call('reader', 'get').expect(200)
    const forbidden = [
      call('reader', 'get', `/${id}`),
      call('reader', 'post', '', body(unique())),
      call('reader', 'put', `/${id}`, {}),
      call('reader', 'delete', `/${id}`),
      call('reader', 'post', '/batch-delete', { ids: [id] }),
      call('plain', 'get'),
    ]
    for (const res of await Promise.all(forbidden)) {
      expect(res.status).toBe(403)
      expect(res.body.code).toBe(Err.FORBIDDEN.code)
    }
  })

  it('400: invalid body / query / id, with translated field messages', async () => {
    const required = (lang: string, field: string) =>
      t(lang, 'validation.required', { field: label(lang, field) })
    expect(label('zh-CN', 'invoiceNo')).not.toMatch(/^field\./)
    expect(label('en-US', 'invoiceNo')).not.toMatch(/^field\./)
    const zh = await create({ ...body(unique()), invoiceNo: '', buyer: 'x'.repeat(129) }).expect(
      400,
    )
    expect(zh.body).toMatchObject({
      code: Err.VALIDATION_FAILED.code,
      msg: required('zh-CN', 'invoiceNo'),
    })
    expect(zh.body.errors).toEqual([
      { path: 'invoiceNo', msg: required('zh-CN', 'invoiceNo') },
      {
        path: 'buyer',
        msg: t('zh-CN', 'validation.too_big.string', {
          field: label('zh-CN', 'buyer'),
          maximum: 128,
        }),
      },
    ])
    const { invoiceNo: _, ...keyless } = body(unique())
    const en = await create(keyless).set('Accept-Language', 'en-US').expect(400)
    expect(en.body.errors).toEqual([{ path: 'invoiceNo', msg: required('en-US', 'invoiceNo') }])
    await call('admin', 'get').query({ sort: 'nope' }).expect(400)
    await call('admin', 'post', '/batch-delete', { ids: [] }).expect(400)
    await call('admin', 'get', '/abc').expect(400)
  })

  it('409 duplicate: a unique value already taken (create and update; case-insensitive)', async () => {
    const tag = unique()
    const taken = await add(body(tag))
    const other = await add(body(unique()))
    for (const res of [
      await create({ ...body(unique()), invoiceNo: taken.invoiceNo.toUpperCase() }),
      await call('admin', 'put', `/${taken.id}`, { invoiceNo: other.invoiceNo }),
    ]) {
      expect(res.status).toBe(409)
      expect(res.body).toMatchObject({
        code: Err.DUPLICATE.code,
        msg: t('zh-CN', Err.DUPLICATE.key),
      })
    }
  })

  it('404: unknown ids for get, update, delete; a batch with one unknown id deletes nothing', async () => {
    const { id } = await add(body(unique()))
    for (const res of [
      await call('admin', 'get', `/${MISSING}`),
      await call('admin', 'put', `/${MISSING}`, {}),
      await call('admin', 'delete', `/${MISSING}`),
      await call('admin', 'post', '/batch-delete', { ids: [id, MISSING] }),
    ]) {
      expect(res.status).toBe(404)
      expect(res.body.code).toBe(Err.NOT_FOUND.code)
    }
    await call('admin', 'get', `/${id}`).expect(200)
  })

  it('the same create submitted twice within 3 s → 429 (@Idempotent)', async () => {
    const tag = unique()
    await create(body(tag)).expect(201)
    const again = await create(body(tag)).expect(429)
    expect(again.body.code).toBe(Err.TOO_MANY_REQUESTS.code)
  })
})

it('@ActionLog: every write leaves a row with domain demo.invoice, its verb and the id', async () => {
  const trace = `${PREFIX}${process.pid}-`
  const created = await create(body(unique())).set('X-Request-Id', `${trace}c`).expect(201)
  const { id } = created.body.data
  await call('admin', 'put', `/${id}`, {}).set('X-Request-Id', `${trace}u`)
  await call('admin', 'delete', `/${id}`).set('X-Request-Id', `${trace}d`)
  await call('admin', 'post', '/batch-delete', { ids: [MISSING] }).set('X-Request-Id', `${trace}b`)
  const expected: [string, object][] = [
    ['c', { verb: 'create', biz_id: String(id), ok: 1 }],
    ['u', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['d', { verb: 'remove', biz_id: String(id), ok: 1 }],
    ['b', { verb: 'remove', biz_id: null, ok: 0, error_msg: Err.NOT_FOUND.key }],
  ]
  for (const [suffix, row] of expected)
    expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
      domain: 'demo.invoice',
      username: 'admin',
      ...row,
    })
})

it('Swagger documents every route', async () => {
  const doc = (await request(app.getHttpServer()).get('/api/docs-json').expect(200)).body
  expect(
    Object.keys(doc.paths)
      .filter((p) => p.startsWith(URL))
      .sort(),
  ).toEqual([URL, `${URL}/batch-delete`, `${URL}/{id}`])
  expect(
    doc.paths[URL].get.responses['200'].content['application/json'].schema.properties.data,
  ).toMatchObject({ properties: { items: { type: 'array' }, total: { type: 'integer' } } })
  // the configured examples
  expect(
    doc.paths[URL].post.requestBody.content['application/json'].schema.properties,
  ).toMatchObject({
    total: { example: 1280.5 },
    state: { example: 'issued' },
  })
})
